param([string]$SuiteRoot)
$ErrorActionPreference='Stop'; Set-Location -LiteralPath $SuiteRoot
$cfg='harness_watcher_implementation/canary-20260801-attention-r14.json'; $identity=Join-Path $SuiteRoot '.agent-workspace/ORCHESTRATOR_HARNESS/20260801-attention-r14_optional_identity.json'; $service=Join-Path $SuiteRoot 'harness_watcher/runs/20260801-attention-r14/watcher/service.json'
& python -m harness_watcher_implementation --config $cfg start --owner-pid $PID | Out-Null; if($LASTEXITCODE -ne 0){throw 'optional start failed'}
$o=Get-Process -Id $PID; $s=Get-Content $service -Raw|ConvertFrom-Json; $j=[ordered]@{schema='canary-optional-watcher-owner/v1';owner=@{pid=$PID;created_utc=$o.StartTime.ToUniversalTime().ToString('o')};config=$cfg;started_utc=[DateTime]::UtcNow.ToString('o');watcher=$s.watcher}; [IO.File]::WriteAllText($identity,($j|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false)); while($true){Start-Sleep 1;$s=Get-Content $service -Raw|ConvertFrom-Json;if($s.exit_reason -or $s.stop_requested){break}}; $j.ended_utc=[DateTime]::UtcNow.ToString('o');$j.exit_reason=$s.exit_reason;[IO.File]::WriteAllText($identity,($j|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
